async function getRecentResult(req) {
    try {
        console.log(`${_module}/getRecentResults req.body.activeWorkspace `, req.query)
        let ctx = await runtime.causeway.getContext()
        let gpt_recent = await ctx.get("openai-recent-result")
        gpt_recent = gpt_recent ? gpt_recent : ""

        // iterate through recent result to check if they exist inside of the flow 
        let flow = runtime._.nodes.getFlow(req.query.activeWorkspace)
        gpt_recent.forEach(cr_set => {
            cr_set.forEach(cr => {
                console.log(`${_module}/getRecentResults cr `, cr)
                let nodePairs = [...cr.label.matchAll(/(\[(.*?)\]\s*-->\s*\[(.*?)\])/gi)]
                let cause = nodePairs[0][2]
                let effect = nodePairs[0][3]
                let causeId = req.query.nn[cause]
                let effectId = req.query.nn[effect]
                console.log(cause, causeId, effect, effectId)

                if (causeId !== undefined) {
                    let causeNode = runtime._.nodes.getNode(causeId)
                    let actuallyAdded = false
                    causeNode.wires[0].forEach(wire => {
                        if (wire === effectId) { actuallyAdded = true }
                    })
                    if (!actuallyAdded) {
                        cr.sublabel = ""
                    }
                } else {
                    cr.sublabel = ""
                }
            })
        })


        console.log(`${_module}/getRecentResults gpt_recent `, gpt_recent)
        return gpt_recent
    }
    catch (exception) {
        console.log(`${_module}/getRecentResults exception `, exception)
        return exception
    }
}

