/** 
 * process response from ChatGPT
 */
async function processGPTResponse(answer) {
    try {
        var nodePairSet = await answer.map(response => {
            let nodePairs = [...response.text.matchAll(/(\[(.*?)\]\s*-->\s*\[(.*?)\])/gi)]
            let listItem = nodePairs.map(pair => {
                let edge = pair[0]
                // prepare item to be added to list as disction
                let node = {
                    "label": edge,
                    "checkbox": true, // (optional) if present, display checkbox accordingly
                    "selected": false, // (optional) whether the item is selected or not
                    "collapsible": true, // prevent a parent item from being collapsed. default true.
                    "sublabel": ""
                }
                return node
            })
            return listItem
        })
        return nodePairSet
    } catch (exception) {
        console.log(`${_module} processGPTResponse exception `, exception)

        throw exception
    }
}

async function getOpenAIResponse(req, res) {
    try {
        var answer = ""
        let ctx = await runtime.causeway.getContext()
        await ctx.set("gpt-api-key", req.query.api_key)
        await ctx.set("gpt-org", req.query.api_org)
        console.log(`${_module} getOpenAIResponse apikey`, req.query.api_key)
        console.log(`${_module} getOpenAIResponse apiorg`, req.query.api_org)

        // set up configuration 
        const configuration = new Configuration({
            apiKey: req.query.api_key,
            organization: req.query.api_org
        })
        const openai = new OpenAIApi(configuration)
        console.log(`${_module} getOpenAIResponse prompt`, req.query.prompt)
        // add "You are a helpful assistant for causal reasoning"
        let prompt = "You are a helpful assistant for causal reasoning\n"
        prompt += req.query.prompt
        console.log(`${_module} prompt`, JSON.stringify(prompt))
        // submit the question to chatGPT
        const response = await openai.createCompletion({
            model: "text-davinci-003",
            prompt: prompt,
            n: 1,
            // stop: "\n",
            max_tokens: 100,
        })
        // const response = await openai.createCompletion({
        //     model: "text-davinci-003",
        //     prompt: "Say this is a test",
        //     max_tokens: 7,
        //     temperature: 0,
        //   });
        var answer = response.data.choices
        let processedAnswered = await processGPTResponse(answer)
        ctx.set("openai-recent-result", processedAnswered)
        delete configuration
        delete openai
        res.status(200).send({ gpt_results: processedAnswered })
        return
    } catch (error) {
        console.log(`${_module} getOpenAIResponse error`, error)
        return error
    }
}

function getAxisValue(min, max, axisValue) {
    let value = Math.ceil(Math.random() * (max - min) + min)
    console.log(`${_module} getAxisValue actual-value`, axisValue)
    console.log(`${_module} getAxisValue new-valuie`, value)
    return axisValue + value
}
